-- =============================================================================
-- POST-IMPORT — FASCE INDICATORI (modello "come lo sheet": 4 bande per indicatore)
-- =============================================================================
-- Da eseguire DOPO import catalogo+misure. Sostituisce l'approccio a 2 soglie.
-- Per ogni indicatore numerico crea una uom_range dedicata (RNG_<codice>) con le
-- 4 fasce reali dello sheet (Range 1-4), rese CONTIGUE (niente buchi che manderebbero
-- DirectRange in errore). Assegna la scala alle misure e imposta lo scoring:
--   weScoreConvEnumId = WECONVER_NOCONVERSIO (valore % passa cosi' com'e')
--   weScoreRangeEnumId = WESCORE_DIRECTRANGE (valore -> banda -> punteggio)
-- Il Target (valore singolo) = confine della banda 100% (ricavato dalla card).
-- SI/NO esclusi (tipologia SI_NO). 163 indicatori.
-- =============================================================================

BEGIN;

-- 0) Pulizia vecchio approccio soglie (transazioni SOGLIA_50/100 non piu' usate)
DELETE FROM acctg_trans_entry WHERE gl_fiscal_type_id IN ('SOGLIA_50','SOGLIA_100');
DELETE FROM acctg_trans       WHERE gl_fiscal_type_id IN ('SOGLIA_50','SOGLIA_100');

