ON CONFLICT (uom_range_values_id) DO NOTHING;

-- 3) assegna scala + scoring diretto alle misure CTX_BS degli indicatori con RNG_
UPDATE work_effort_measure wem
SET uom_range_id = 'RNG_'||g.account_code,
    we_score_range_enum_id = 'WESCORE_DIRECTRANGE',
    we_score_conv_enum_id  = 'WECONVER_NOCONVERSIO',
    last_updated_stamp = NOW(), last_updated_tx_stamp = NOW()
FROM gl_account g, work_effort we
WHERE g.gl_account_id = wem.gl_account_id
  AND we.work_effort_id = wem.work_effort_id AND we.work_effort_type_id = 'CTX_BS'
  AND EXISTS (SELECT 1 FROM uom_range r WHERE r.uom_range_id = 'RNG_'||g.account_code);

COMMIT;

